@implemented
class NullHost(Host):
    "A host with no folders and no services, which refuses every file operation."
    writes = False   # `file_tools` then withholds the editors
    def __init__(self, roots=()): self._roots = [str(r) for r in roots]
    @property
    def roots(self): return self._roots
    def check(self, path, must_exist=False, reading=False): raise HostError(f'{NO_ROOTS}: {path}')
    def walk(self): return []
    def read(self, path): return None
    def write(self, path, text): raise HostError('this host cannot write')
    def delete(self, path): raise HostError('this host cannot delete')
    def exists(self, path): return False
    def text_at(self, path): return None


@patch
def delete(self:LocalHost, path):
    "Remove one file inside the roots; one already gone is not an error."
    self.check(path).unlink(missing_ok=True)

@patch
def exists(self:LocalHost, path):
    "Whether `path` is a file inside the roots (an undecodable file counts)."
    try: return self.check(path).exists()
    except Exception: return False

