def tools_for(host, get_skills=None, extra=(), mx=MAX_TOOL_CHARS, drop=(), get_spec=None, on_media=None, optin=()):
    "The tools for `host`: a group per capability it declares, plus skills, images and extensions, less `drop` and plus `optin`."
    # `generate_image` saves files, so it needs a writable host
    image = (image_tools(host, mx, get_spec=get_spec, on_media=on_media)
             if not isinstance(image_route(), str) and host.writes and 'image' not in set(drop or ()) else None)
    tools = _tools_for(host, get_skills=get_skills, extra=extra, mx=mx, drop=drop, image=image, optin=optin)
    # `LocalHost.search` fuses its legs with litesearch
    if isinstance(host, LocalHost) and not installed('litesearch'): tools = [t for t in tools if t.__name__ != 'search_code']
    return tools

def small_tool(f):
    "Mark an extension tool for the small profile, whose catalog omits unmarked tools."
    f.small = True
    return f

@dataclass(frozen=True)
class ToolEntry:
    "One callable and the Shalya metadata every consumer needs."
    tool: object
    group: str = ''

    @property
    def name(self): return getattr(self.tool, '__name__', '')
    @property
    def writes(self): return is_write(self.tool)
    @property
    def effects(self): return has_effect(self.tool)
    @property
    def available(self): return callable(self.tool)
    def describe(self, args=None): return summarise(self.tool, args)


class ToolCatalog:
    "An immutable list of tools that answers each one's group, whether it writes, and whether it has effects."
    def __init__(self, tools=()):
        self.entries = tuple(ToolEntry(t, group_of(getattr(t, '__name__', ''), 'extension'))
                             for t in tools)
        self._by_name = {e.name: e for e in self.entries}
        self._tools = [e.tool for e in self.entries]
    def __iter__(self): return iter(self.entries)
    def __len__(self): return len(self.entries)
    def __getitem__(self, name): return self._by_name[name]
    @property
    def tools(self): return self._tools
    @property
    def names(self): return frozenset(self._by_name)
    @property
    def writes(self): return frozenset(e.name for e in self.entries if e.writes)
    def summarise(self, name, args=None): return self[name].describe(args)
    def read_only(self, max_calls=None, writes=False, effects=True, block=()):
        return type(self)(read_only(self.tools, max_calls, writes, effects, block))
    def map(self, fn): return type(self)(fn(e.tool) for e in self.entries)


